int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_ticket *ticket = NULL;
    struct ceph_auth_ticket_handler *handler = NULL;
    void *ticket_data = NULL;
    size_t ticket_len;

    if (!ac || !secret || !p || !*p || *p > end) {
        goto out;
    }

    /* Decode ticket type and version */
    le32 dec_type = ceph_decode_32(p);
    le32 version = ceph_decode_32(p);
    if (p > &end) {
        goto out;
    }

    /* Retrieve ticket handler */
    handler = get_ticket_handler(ac, dec_type);
    if (!handler) {
        goto out;
    }

    /* Decode ticket length */
    ticket_len = le32_to_cpu(ceph_decode_32(p));
    if (p + ticket_len > end) {
        goto out;
    }

    ticket_data = *p;
    *p += ticket_len;

    /* Allocate and decode ticket structure */
    ticket = kmalloc(sizeof(*ticket), GFP_NOFS);
    if (!ticket) {
        goto out;
    }

    ticket->version = version;
    ticket->data = kmemdup(ticket_data, ticket_len, GFP_NOFS);
    if (!ticket->data) {
        goto out;
    }
    ticket->data_len = ticket_len;

    /* Decrypt if necessary */
    if (handler->encrypted) {
        ret = decrypt_ticket(ticket, secret);
        if (ret < 0) {
            goto out;
        }
    } else {
        /* Copy session key directly */
        memcpy(&ac->session_key, ticket->data, sizeof(ac->session_key));
    }

    /* Update validity and session info */
    ret = update_session_info(ac, ticket);
    if (ret < 0) {
        goto out;
    }

    /* Update ticket blob and validity in handler */
    handler->blob = ticket->data;
    handler->blob_len = ticket->data_len;
    handler->valid = true;

    ret = 0;
out:
    if (ticket) {
        kfree(ticket->data);
        kfree(ticket);
    }
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
  int ret = -EINVAL;
  void *ticket_blob = NULL;
  struct ceph_ticket *ticket = NULL;
  struct ceph_auth_client_ticket_handler *handler = NULL;
  void *ticket_data = NULL;
  size_t ticket_data_len = 0;
  struct ceph_crypto_key session_key;
  int encrypted = 0;

  // Decode ticket type and structure version
  if ((end - *p) < sizeof(*ticket)) {
    goto out;
  }

  ticket = (struct ceph_ticket *)(*p);
  (*p) += sizeof(*ticket);

  // Retrieve ticket handler
  handler = ceph_auth_client_get_ticket_handler(ac, ticket->type);
  if (!handler) {
    goto out;
  }

  // Allocate memory for the ticket blob
  ticket_blob = kmalloc(ticket->blob_length, GFP_NOFS);
  if (!ticket_blob) {
    ret = -ENOMEM;
    goto out;
  }

  // Copy or decrypt ticket blob
  if (encrypted) {
    // Decrypt using the old session key
    ret = ceph_crypto_decrypt(secret, *p, ticket->blob_length, ticket_blob);
    if (ret < 0) {
      goto out;
    }
  } else {
    // Directly copy the data
    if ((end - *p) < ticket->blob_length) {
      ret = -EINVAL;
      goto out;
    }
    memcpy(ticket_blob, *p, ticket->blob_length);
    *p += ticket->blob_length;
  }

  // Update session key and validity info from ticket
  ret = handler->parse_ticket(ticket_blob, ticket->blob_length, &session_key, &ticket_data, &ticket_data_len);
  if (ret < 0) {
    goto out;
  }

  // Set the new session key
  ceph_crypto_key_destroy(&ac->session_key);
  ac->session_key = session_key;

  // Update ticket handler with new data
  handler->set_ticket_data(ac, ticket_data, ticket_data_len);

out:
  if (ticket) {
    kfree(ticket);
  }

  if (ticket_blob) {
    kfree(ticket_blob);
  }

  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler = NULL;
    void *ticket_blob = NULL;
    void *decrypted_blob = NULL;
    size_t ticket_blob_len = 0;
    size_t decrypted_len = 0;

    if (!ac || !secret || !p || !end || *p >= end) {
        goto out;
    }

    /* decode ticket type and version */
    le32_to_cpu(p, end, &handler_type);
    le32_to_cpu(p, end, &version);
    handler = ceph_get_ticket_handler(handler_type);
    if (!handler) {
        goto out;
    }

    /* decode ticket blob length */
    le32_to_cpu(p, end, &ticket_blob_len);
    if ((void *)*p + ticket_blob_len > end) {
        goto out;
    }

    ticket_blob = *p;
    *p += ticket_blob_len;

    if (handler->decrypt_ticket) {
        ret = handler->decrypt_ticket(secret, ticket_blob, ticket_blob_len,
                                      &decrypted_blob, &decrypted_len);
        if (ret < 0) {
            goto out;
        }
    } else {
        decrypted_blob = malloc(decrypted_len);
        if (!decrypted_blob) {
            ret = -ENOMEM;
            goto out;
        }
        memcpy(decrypted_blob, ticket_blob, decrypted_len);
    }

    /* decode session key and validity */
    ret = ceph_decode_session_key(decrypted_blob, decrypted_len,
                                    &ac->session_key, &ac->valid_until);
    if (ret < 0) {
        goto out;
    }

    handler->ticket_blob = decrypted_blob;
    handler->valid_until = ac->valid_until;

    ret = 0;

out:
    if (ret < 0) {
        free(decrypted_blob);
    }
    ceph_put_ticket_handler(handler);
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = 0;
    struct ceph_auth_ticket_handler *handler;
    void *data, *decrypted;
    size_t len;

    // Decode ticket type and version
    le32_decoded ticket_type;
    le32_decoded version;
    if ((void*)(p + sizeof(ticket_type)) > end) {
        return -EINVAL;
    }
    ceph_decode_copy(p, &ticket_type, sizeof(ticket_type));
    ceph_decode_copy(p, &version, sizeof(version));

    // Retrieve handler
    handler = ceph_get_ticket_handler(ac, le32_to_cpu(ticket_type));
    if (!handler) {
        return -ENOENT;
    }

    // Decode encrypted data
    le64_decoded enc_len;
    ceph_decode_copy(p, &enc_len, sizeof(enc_len));
    len = le64_to_cpu(enc_len);
    if ((void*)(p + len) > end) {
        return -EINVAL;
    }
    data = *p;
    *p += len;

    // Decrypt data if needed
    if (handler->encrypted) {
        decrypted = ceph_decrypt_data(data, len, secret);
        if (!decrypted) {
            return -EIO;
        }
        data = decrypted;
    }

    // Update session key and validity
    if (ceph_update_session_key(ac, data, len) < 0) {
        ret = -EIO;
        goto out;
    }

    if (ceph_update_validity(ac, data, len) < 0) {
        ret = -EIO;
        goto out;
    }

    // Update ticket blob and validity in handler
    handler->blob = data;
    handler->valid = 1;

out:
    if (handler->encrypted && decrypted) {
        ceph_free(decrypted);
    }
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler = NULL;
    void *ticket_blob = NULL;
    void *decrypted_blob = NULL;
    int ticket_type, version;

    if (!ac || !secret || !p || !*p || !end || *p >= end) {
        goto out;
    }

    /* decode ticket type and version */
    if ((end - *p) < sizeof(int) * 2) {
        goto out;
    }
    ticket_type = ceph_decode_32(p);
    version = ceph_decode_32(p);

    handler = ceph_get_ticket_handler(ac, ticket_type);
    if (!handler) {
        goto out;
    }

    /* read ticket blob length and data */
    if ((end - *p) < sizeof(int)) {
        goto out;
    }
    int blob_len = ceph_decode_32(p);
    if (blob_len < 0 || (end - *p) < blob_len) {
        goto out;
    }
    ticket_blob = *p;
    *p += blob_len;

    if (version < 1 || version > CEPH_AUTH_TICKET_LATEST_VERSION) {
        goto out;
    }

    /* decrypt the ticket blob */
    decrypted_blob = malloc(blob_len);
    if (!decrypted_blob) {
        goto out;
    }

    if (secret) {
        ret = ceph_crypto_decrypt(secret, ticket_blob, blob_len, decrypted_blob, &blob_len);
        if (ret < 0) {
            goto out;
        }
    } else {
        memcpy(decrypted_blob, ticket_blob, blob_len);
    }

    /* update session key and validity info */
    ret = ceph_update_session_key(ac, decrypted_blob, blob_len, handler);
    if (ret < 0) {
        goto out;
    }

    handler->blob = ticket_blob;
    handler->blob_len = blob_len;
    handler->valid = 1;

    ret = 0;

out:
    if (handler) {
        ceph_put_ticket_handler(ac, handler);
    }
    if (decrypted_blob) {
        free(decrypted_blob);
    }
    return ret;
}
